destination-australia.rawStyle:
/* ===== Australia: page-scoped composition (no global edits) ===== */
.dp-hero{text-align:left;overflow:hidden;isolation:isolate}
.dp-hero:after{background:linear-gradient(96deg,rgba(0,0,0.72) 0%,rgba(0,0,0.48) 32%,rgba(0,0,0.14) 60%,transparent 78%),linear-gradient(180deg,rgba(0,0,0.2) 0%,transparent 32%,transparent 60%,rgba(0,0,0.46) 100%)!important}
.dp-hero .hero-inner{max-width:none;width:100%}
.dp-hero .dp-copy{max-width:700px}
.dp-hero .display{font-size:clamp(52px,8.4vw,118px);line-height:.98;margin:0;letter-spacing:-.01em}
.dp-hero .lede{max-width:46ch;margin-top:22px}
.dp-hero .dp-cta{display:flex;align-items:center;gap:30px;margin-top:36px;flex-wrap:wrap}
.btn-square{border-radius:2px!important;padding:16px 36px!important;letter-spacing:.03em;font-weight:600}
.dp-meta{position:absolute;right:var(--gutter);bottom:38px;z-index:2;text-align:right;color:#fff;text-shadow:var(--shadow-dark)}
.dp-meta .k{font-family:var(--fr);font-weight:600;font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:rgba(255,255,255.74)}
.dp-meta .t{font-family:var(--logo);font-style:italic;font-size:22px;line-height:1.2;margin-top:4px}
@media(max-width:820px){.dp-meta{display:none}}
.dp-hero .hero-inner .eyebrow.on-dark{display:flex;flex-wrap:wrap;column-gap:.5ch;row-gap:6px;max-width:100%}
@media(max-width:480px){.dp-hero .hero-inner .eyebrow.on-dark{letter-spacing:.1em}}

.idx{list-style:none;margin:30px 0 0;padding:0;counter-reset:ix}
.idx li{counter-increment:ix;display:grid;grid-template-columns:auto 1fr;gap:20px;align-items:baseline;padding:20px 0;border-top:1px solid var(--line)}
.idx li:last-child{border-bottom:1px solid var(--line)}
.idx li:before{content:counter(ix,decimal-leading-zero);font-family:var(--logo);font-style:italic;font-size:26px;color:var(--accent-2);line-height:1}
.idx p{margin:0;font-size:16.5px;line-height:1.55;color:var(--ink)}

.ov{position:relative}
.ov-img{height:clamp(360px,52vw,620px);border-radius:4px;background-size:cover;background-position:center;filter:contrast(1.04)}
.ov-card{background:var(--ivory);border:1px solid var(--line);border-radius:4px;padding:clamp(26px,3vw,40px);box-shadow:0 30px 70px rgba(0,0,0.1)}
@media(min-width:921px){.ov-card{position:relative;margin:-90px -40px 0 0;z-index:2}}
.stay{padding:20px 0;border-top:1px solid var(--line-soft)}
.stay:first-child{border-top:0;padding-top:0}
.stay .place{font-family:var(--fr);font-weight:600;font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--accent-2)}
.stay h4{font-family:var(--logo);font-weight:500;font-size:clamp(23px,2.2vw,29px);line-height:1.12;margin:5px 0 6px}
.stay p{color:var(--ink-soft);font-size:15.5px;line-height:1.55;margin:0;max-width:52ch;text-wrap:pretty}

.sig{position:relative;min-height:78svh;display:flex;align-items:flex-end;color:#fff;background-size:cover;background-position:center;background-color:#111}
.sig:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0.1),rgba(0,0,0.16) 46%,rgba(0,0,0.7))}
.sig .wrap{position:relative;z-index:1;padding-top:clamp(80px,16vh,180px);padding-bottom:clamp(54px,9vh,90px)}
.sig .pull{font-family:var(--logo);font-weight:500;font-size:clamp(34px,5.4vw,76px);line-height:1.05;letter-spacing:-.012em;max-width:18ch;text-shadow:0 2px 30px rgba(0,0,0.5)}
.sig .by{font-family:var(--fr);font-weight:600;font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255.78);margin-bottom:20px}

.when{font-size:clamp(22px,2.4vw,30px);font-family:var(--logo);font-weight:500;line-height:1.3;color:var(--ink);max-width:32ch}
.vrow{display:grid;grid-template-columns:1.1fr 1fr;gap:clamp(34px,5vw,80px);align-items:center}
@media(max-width:900px){.vrow{grid-template-columns:1fr;gap:32px}}
.cp-lines{list-style:none;margin:24px 0 0;max-width:none}
.cp-lines li{display:flex;gap:13px;align-items:flex-start;padding:14px 0;border-top:1px solid var(--line);font-size:16px;line-height:1.55;color:var(--ink)}
.cp-lines li:last-child{border-bottom:1px solid var(--line)}
.cp-lines li .ck{flex:0 0 auto;color:var(--accent-2);font-size:14px;margin-top:3px}

