/* ---- Maison hero ---- */
.hero-cp{position:relative;isolation:isolate;overflow:hidden}
.hero-cp:after{background:
  linear-gradient(100deg,rgba(0,0,0.72) 0%,rgba(0,0,0.5) 30%,rgba(0,0,0.15) 58%,transparent 76%),
  linear-gradient(180deg,rgba(0,0,0.2) 0%,transparent 32%,transparent 58%,rgba(0,0,0.5) 100%)}
.hero-cp .hero-inner{max-width:none;width:100%}
.hero-cp .hs-copy{max-width:680px}
.hero-cp .display{font-size:clamp(54px,8.5vw,116px);line-height:.98;margin:0;letter-spacing:-.01em}
